// Lit le message Razmo : commande, carburant, seuil (1,65 -> 1.65), lieu, payload /start a_gazole_165_94000
const MAP = { gazole: 'gazole', diesel: 'gazole', gasoil: 'gazole', gazoil: 'gazole', sp95: 'sp95', '95': 'sp95', e10: 'e10', sp95e10: 'e10', sp98: 'sp98', '98': 'sp98', e85: 'e85', gplc: 'gplc', gpl: 'gplc' };
const norm = w => MAP[String(w || '').toLowerCase().replace(/[\s-]/g, '')] || '';
const toNum = s => /^\d+([.,]\d+)?$/.test(String(s || '')) ? parseFloat(String(s).replace(',', '.')) : NaN;
const m = $input.first().json.message || {};
const text = String(m.text || '').trim();
const chat_id = String((m.chat && m.chat.id) || '');
const cmd = ((text.match(/^\/(\w+)/) || [])[1] || '').toLowerCase();
const args = text.split(/\s+/).slice(1);
let command = 'menu', source = 'command', fuel = '', threshold = null, place = '', n = null;
if (cmd === 'start' && /^a_/.test(args[0] || '')) {
  const p = args[0].split('_');
  command = 'alerte'; source = 'deeplink'; fuel = norm(p[1]);
  const c = parseInt(p[2], 10); threshold = Number.isFinite(c) ? c / 100 : null; place = p[3] || '';
} else if (cmd === 'start') command = 'start';
else if (cmd === 'alerte') { command = 'alerte'; fuel = norm(args[0]); const t = toNum(args[1]); threshold = Number.isFinite(t) ? t : null; place = args.slice(2).join(' '); }
else if (cmd === 'mesalertes') command = 'list';
else if (cmd === 'stop') { command = 'stop'; const k = parseInt(args[0], 10); n = Number.isFinite(k) ? k : null; }
else if (cmd === 'tendance') command = 'trend';
else if (cmd === 'sweep') command = 'sweep';
else if (cmd === 'panne') command = 'drill';
const threshold_ok = threshold !== null && threshold >= 0.5 && threshold <= 3.5;
return [{ json: { chat_id, text, command, source, fuel, threshold, threshold_ok, place, n } }];

// Menu de Razmo ; signale si l'utilisateur vient d'etre enregistre comme proprietaire
const q = $('Read the message').first().json;
let owner = false;
try { owner = $('Register owner').isExecuted; } catch (e) { owner = false; }
const text = (owner ? 'Razmo te reconnaît comme chef. Toi seul peux lancer /sweep.\n\n' : '')
  + '🐀 <b>Razmo surveille les pompes. Razmo patient.</b>\n\n'
  + '<code>/alerte gazole 1,65 Créteil</code> : Razmo te prévient quand le prix passe sous ton seuil.\n'
  + '<code>/mesalertes</code> : ce que Razmo surveille.\n'
  + '<code>/stop 2</code> : Razmo arrête l\'alerte n°2.\n'
  + '<code>/tendance</code> : le prix le plus bas par jour, sur 7 jours.\n'
  + '<code>/sweep</code> et <code>/panne</code> : réservés au chef (tournée immédiate, test de panne).\n\n'
  + 'Razmo fait sa tournée à 7 h et 18 h. Pour une pompe tout de suite, demande à Rapido : @rapido_carbu_bot';
return [{ json: { chat_id: q.chat_id, text } }];

// Explique ce qui cloche dans l'alerte (voix de Razmo) + message d'usage
const q = $('Read the message').first().json;
const g = $input.first().json;
let why = 'Razmo trouve pas ce lieu sur sa carte.';
if (g.error) why = 'Les pompes répondent pas à Razmo. Razmo réessaie plus tard. Razmo patient.';
else if (!q.fuel) why = 'Razmo connaît pas ce carburant.';
else if (!q.threshold_ok) why = 'Razmo veut un seuil entre 0,50 et 3,50 €.';
else if (!q.place) why = 'Razmo veut savoir où surveiller.';
const text = why + '\n\nRazmo explique : <code>/alerte gazole 1,65 Créteil</code>\nCarburants : gazole, sp95, e10, sp98, e85, gplc.';
return [{ json: { chat_id: q.chat_id, text } }];

// Confirme l'alerte dans la voix de Razmo
const a = $('Shape alert record').first().json;
const e = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fuel = String(a.fuel || '');
const seuil = Number(a.threshold).toFixed(2).replace('.', ',');
const text = 'Razmo a compris. <b>' + e(fuel.charAt(0).toUpperCase() + fuel.slice(1)) + ' sous ' + seuil + ' €</b> à ' + e(a.place_label) + '. Razmo bouge pas de la pompe.\n\nRazmo fait sa tournée à 7 h et 18 h.';
return [{ json: { chat_id: a.chat_id, text } }];

// Decoupe chaque message en morceaux de moins de 4000 caracteres (limite Telegram)
const out = [];
for (const it of $input.all()) {
  let rest = String(it.json.text || '');
  while (rest.length > 3900) {
    let cut = rest.lastIndexOf('\n', 3900);
    if (cut < 1000) cut = 3900;
    out.push({ json: { chat_id: it.json.chat_id, text: rest.slice(0, cut) } });
    rest = rest.slice(cut);
  }
  if (rest.trim()) out.push({ json: { chat_id: it.json.chat_id, text: rest } });
}
return out;

// Liste numerotee des alertes actives (le numero sert a /stop)
const q = $('Read the message').first().json;
const e = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(r => r.id);
if (!rows.length) return [{ json: { chat_id: q.chat_id, text: 'Razmo surveille rien pour toi. Essaie <code>/alerte gazole 1,65 Créteil</code>.' } }];
const lines = rows.map((r, i) => (i + 1) + '. ' + e(r.fuel) + ' sous <b>' + Number(r.threshold).toFixed(2).replace('.', ',') + ' €</b> à ' + e(r.place_label) + (r.armed ? '' : ' (déjà sonnée, Razmo attend que ça remonte)'));
return [{ json: { chat_id: q.chat_id, text: 'Razmo surveille ça pour toi :\n\n' + lines.join('\n') + '\n\nPour arrêter : <code>/stop 1</code>' } }];

// Retrouve l'alerte n (meme numerotation que /mesalertes)
const q = $('Read the message').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id);
const r = q.n ? rows[q.n - 1] : null;
return [{ json: { found: !!r, row_id: r ? r.id : null, fuel: r ? r.fuel : '', place_label: r ? r.place_label : '', count: rows.length } }];

// Confirme l'arret de l'alerte ou explique /stop
const q = $('Read the message').first().json;
const p = $('Pick alert to stop').first().json;
const e = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let text;
if (p.found) text = 'Razmo arrête de surveiller le ' + e(p.fuel) + ' à ' + e(p.place_label) + '. Razmo range ses jumelles.';
else if (!p.count) text = 'Razmo surveille rien pour toi. Rien à arrêter.';
else text = 'Razmo trouve pas cette alerte. Regarde <code>/mesalertes</code> puis <code>/stop 1</code>.';
return [{ json: { chat_id: q.chat_id, text } }];

// Minimum par jour sur 7 jours (price_history), limite aux lieux/carburants des alertes de l'utilisateur si possible
const q = $('Read the message').first().json;
const e = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mine = $('Read my alerts (trend)').all().map(i => i.json).filter(r => r.id).map(r => r.place_label + '|' + r.fuel);
let rows = $input.all().map(i => i.json).filter(r => r.id);
const own = rows.filter(r => mine.includes(r.place_label + '|' + r.fuel));
if (own.length) rows = own;
if (!rows.length) return [{ json: { chat_id: q.chat_id, text: "Razmo a pas encore d'historique. Razmo note les prix à chaque tournée, à 7 h et 18 h." } }];
const groups = {};
for (const r of rows) {
  const k = r.fuel + ' · ' + r.place_label;
  const d = DateTime.fromISO(String(r.day)).setZone('Europe/Paris').toFormat('dd/MM');
  groups[k] = groups[k] || {};
  if (groups[k][d] === undefined || r.min_price < groups[k][d]) groups[k][d] = r.min_price;
}
const blocks = Object.entries(groups).slice(0, 10).map(([k, days]) => '<b>' + e(k) + '</b>\n' + Object.entries(days).map(([d, v]) => d + ' : ' + Number(v).toFixed(3).replace(/0$/, '').replace('.', ',') + ' €').join('\n'));
return [{ json: { chat_id: q.chat_id, text: 'Razmo a noté le prix le plus bas, jour par jour (7 jours) :\n\n' + blocks.join('\n\n') } }];

// Compte rendu du /sweep dans la voix de Razmo
const q = $('Read the message').first().json;
const s = $input.first().json || {};
if (s.error) return [{ json: { chat_id: q.chat_id, text: 'Les pompes répondent pas à Razmo. Razmo réessaie plus tard. Razmo patient.' } }];
const checked = s.checked || 0, fired = s.fired || 0;
return [{ json: { chat_id: q.chat_id, text: 'Razmo a fait sa tournée : ' + checked + ' alerte(s) vérifiée(s), ' + fired + ' ping(s) envoyé(s).' } }];

// /sweep refuse : reserve au proprietaire
const q = $('Read the message').first().json;
return [{ json: { chat_id: q.chat_id, text: "Razmo fait sa tournée tout seul, à 7 h et 18 h. /sweep, c'est réservé au chef." } }];

// /panne refuse : reserve au proprietaire
const q = $('Read the message').first().json;
return [{ json: { chat_id: q.chat_id, text: "Razmo casse rien sans l'accord du chef. /panne, c'est réservé au chef." } }];
